def to_base(number, base):
    if base < 2 or base > 36:
        raise ValueError("base must be between 2 and 36")

    if number == 0:
        return "0"

    negative = number < 0
    number = abs(number)

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = []

    while number > 0:
        result.append(digits[number % base])
        number //= base

    result.reverse()
    result_str = "".join(result)

    if negative:
        result_str = "-" + result_str

    return result_str


def from_base(text, base):
    if base < 2 or base > 36:
        raise ValueError("base must be between 2 and 36")

    if not text:
        raise ValueError("empty string")

    if text == "-":
        raise ValueError("lone minus sign")

    negative = False
    if text.startswith("-"):
        negative = True
        text = text[1:]

    digits = "0123456789abcdefghijklmnopqrstuvwxyz"
    result = 0

    for char in text:
        char_lower = char.lower()
        if char_lower not in digits:
            raise ValueError(f"invalid character: {char}")
        digit_value = digits.index(char_lower)
        if digit_value >= base:
            raise ValueError(f"digit not valid in base {base}")
        result = result * base + digit_value

    if negative:
        result = -result

    return result
